<script setup>import { onMounted, ref } from "vue"; import AdminLayout from "../../layouts/AdminLayout.vue"; import { requestService } from "../../services/api"; const items = ref([]), error = ref(""), toast = ref(""); const load = async () => { try { items.value = (await requestService.pending()).data; } catch (exception) { error.value = exception.message; } }; const approve = async (item) => { try { await requestService.approve(item.id); toast.value = "Demande approuvée."; await load(); } catch (exception) { error.value = exception.message; } }; const reject = async (item) => { const motif_refus = prompt("Motif du refus :"); if (!motif_refus?.trim()) return; try { await requestService.reject(item.id, { motif_refus }); toast.value = "Demande refusée."; await load(); } catch (exception) { error.value = exception.message; } }; onMounted(load);</script><template><AdminLayout><section class="p-5 md:p-10"><h1 class="text-3xl font-bold">Demandes en attente</h1><p class="mt-2 text-slate-500">Le stock est mis à jour uniquement par le backend après approbation.</p><div v-if="error" class="alert alert-error mt-6">{{ error }}</div><div v-else class="mt-7 overflow-x-auto rounded-2xl bg-white shadow-sm"><table class="table"><thead><tr><th>Utilisateur</th><th>Matériel</th><th>Qté</th><th>Type</th><th>Début</th><th>Retour</th><th>Motif</th><th></th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>#{{ item.utilisateur_id }}</td><td>#{{ item.materiel_id }}</td><td>{{ item.quantite }}</td><td>{{ item.type_emprunt }}</td><td>{{ item.date_debut || '—' }}</td><td>{{ item.date_fin_prevue || '—' }}</td><td class="max-w-48 truncate">{{ item.motif }}</td><td class="flex gap-2"><button class="btn btn-success btn-xs" @click="approve(item)">Approuver</button><button class="btn btn-error btn-xs" @click="reject(item)">Refuser</button></td></tr><tr v-if="!items.length"><td colspan="8" class="py-10 text-center text-slate-500">Aucune demande en attente.</td></tr></tbody></table></div><div v-if="toast" class="toast toast-end"><div class="alert alert-success">{{ toast }}</div></div></section></AdminLayout></template>
